INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-bosque-viviente-en-el-viento', 'El Bosque Viviente en el Viento', 'Dinámica de sensibilidad ecológica y expresión motriz donde los scouts representan árboles de un bosque reaccionando al soplo de la brisa.', '<h2>📜 Descripción de El Bosque Viviente en el Viento</h2>
<p><b>El Bosque Viviente en el Viento</b> es una dinámica scout de educación ambiental, expresión corporal y contención kinésica. En esta actividad, cada participante recibe hojas de papel periódico sobre el césped o suelo de la sala para simular la tierra firme donde echan raíces. Los beneficiarios se transforman en árboles centenarios: sus pies representan las raíces firmes, sus troncos la estructura de madera, y sus brazos extendidos junto a trozos de papel representan las ramas y hojas. El dirigente relata el clima del día (ej. <i>''Brisa suave de mañana''</i>, <i>''Viento fuerte de cordillera''</i> o <i>''Tormenta nocturna''</i>) y los scouts deben mover sus segmentos corporales con elasticidad y ritmo adaptativo.</p>
<p>Esta dinámica desarrolla la apreciación de la naturaleza, el control rítmico y la distensión en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Bosque Viviente en el Viento?</h2>
<p>Para llevar a cabo la dinámica con solemnidad y ritmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Plantación de las Raíces:</b> Cada scout ubica sus hojas de periódico en el campo a una distancia prudente de sus compañeros y se posiciona descalzo o en calzado cómodo sobre ellas.</li>
  <li><b>Nacimiento del Árbol:</b> El animador indica la especie del árbol que representará cada patrulla o seisena (ej. <i>''Araucarias''</i>, <i>''Alerces''</i> o <i>''Robles''</i>).</li>
  <li><b>La Narración del Clima:</b> El dirigente comienza la narración ambiental describiendo los cambios del tiempo meteorológico en el bosque scout.</li>
  <li><b>Movimiento de Ramas y Hojas:</b> Los beneficiarios mecen sus brazos, troncos y papeles respetando estrictamente la intensidad de la brisa narrada sin despegar las raíces de su hoja base.</li>
  <li><b>Unión de la Arboleda:</b> Al final del relato, los árboles entrelazan sus ramas perimetrales formando un gran dosel protector de la arboleda comunitaria.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Bosque Viviente en el Viento</h2>
<p>La actividad reconoce el respeto ecológico y la motricidad fina en el Tally:</p>
<ul>
  <li><b>Mayor Armonía Rítmica:</b> Otorgar 5 puntos a la patrulla o seisena que interprete los cambios del viento con mayor fluidez.</li>
  <li><b>Firmeza de Raíces:</b> Otorgar 3 puntos a los participantes que mantengan la estabilidad sobre su hoja base en todo momento.</li>
  <li><b>Espíritu de Conservación:</b> Otorgar 3 puntos a la unidad que explique con mayor profundidad el valor de proteger los bosques nativos.</li>
</ul>', '/uploads/el-bosque-viviente-en-el-viento.webp', 'publicado', '{"areas": ["espiritualidad", "corporalidad", "sociabilidad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Papel"], "objetivos": ["Desarrollar la motricidad", "Conocer las capacidades corporales", "Crear un ambiente de distensión", "Trabajo en equipo"], "justificacion_areas": "El Bosque Viviente en el Viento potencia la espiritualidad al conectar a los beneficiarios con la maravilla de la Creación y la conservación responsable de la naturaleza. Desarrolla la corporalidad al afianzar el equilibrio, la flexibilidad tónica de brazos y el control del eje corporal. Fortalece la sociabilidad al promover el trabajo armónico y la cohesión de grupo.", "variaciones": "<b>Bosque en Cuatro Estaciones:</b> Variar los movimientos según la estación del año (ej. caída de hojas en otoño, nieve en invierno, florecimiento en primavera).<br><b>Bosque de Noche:</b> Realizar la dinámica con las luces apagadas utilizando la luz de linternas reflejadas en el techo.<br><b>El Bosque y los Animales Scouts:</b> Un grupo de lobatos interpreta animales que buscan refugio entre las ramas del bosque.", "recomendaciones": "Asegurar que los papeles colocados en el suelo no resbalen. Recoger todos los materiales al terminar para promover el hábito de no dejar rastro en el espacio educativo.", "objetivos_educativos": [{"id": "8e6e41e8-5ac4-48a0-82bc-08fe0461a18e", "area": "Espiritualidad", "unidad": "Manada", "texto": "He aprendido a reconocer la naturaleza como obra de Dios.", "como_se_cumple": "Reconociendo en la belleza y movimiento de los árboles la obra creadora de Dios."}, {"id": "4c30bc21-ce45-4e13-995d-d9e0cce0159d", "area": "Espiritualidad", "unidad": "Manada", "texto": "Me gusta cuando las personas hacen cosas buenas por los demás.", "como_se_cumple": "Valorando el esfuerzo de mis compañeros por cuidar la arboleda comunitaria."}, {"id": "8d4dc6a3-8e3a-45c5-b440-6cf075c44e82", "area": "Espiritualidad", "unidad": "Compañía", "texto": "Escucho a las demás y aprendo de ellas.", "como_se_cumple": "Escuchando con atención las reflexiones de la patrulla sobre la conservación del medio ambiente."}, {"id": "a533450a-b017-427b-9e4e-9910f097a9b9", "area": "Espiritualidad", "unidad": "Compañía", "texto": "Procuro que en mi patrulla nos escuchemos y aprendamos unas de otras.", "como_se_cumple": "Promoviendo el respeto por la naturaleza como regalo recibido para proteger."}, {"id": "58925561-3ea5-4144-a704-52e21dd78a3f", "area": "Espiritualidad", "unidad": "Tropa", "texto": "Escucho a los demás y aprendo de ellos.", "como_se_cumple": "Aprendiendo de las vivencias al aire libre y la protección de los bosques nativos."}, {"id": "1311db4d-dddf-4870-9cb3-7403223abb6d", "area": "Espiritualidad", "unidad": "Tropa", "texto": "Procuro que en mi patrulla nos escuchemos y aprendamos unos de otros.", "como_se_cumple": "Fomentando un ambiente de oración y gratitud por la naturaleza en la Tropa."}, {"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Disfrutando del control tónico y el movimiento rítmico de ramas al aire libre."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Afinando el equilibrio tónico manteniendo la firmeza sobre la hoja base."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Respetando las normas de distancia y balanceo rítmico entre árboles."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo elasticidad y precisión en la extensión de brazos y tronco."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Desarrollando la motricidad adaptativa en ejercicios de expresión ambiental."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Perfeccionando el control del centro de gravedad durante soplos de viento simulados."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con lealtad el espacio de cada árbol del bosque."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Acatando los ritmos de narración del dirigente sin romper la formación."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Promoviendo el respeto por el espacio vital de las compañeras de la arboleda."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Favoreciendo la integración armónica y la protección comunitaria en el grupo."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Fomentando el espíritu de lealtad y apoyo mutuo entre las patrullas."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Asumiendo la preservación ecológica como un compromiso ético de la Tropa."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

